// Package summary maintains each project's 1-2 line summary (generated by Haiku).
package summary

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"log"
	"sort"
	"strings"
	"sync"
	"time"

	"github.com/S-kkipie/quorum/internal/hub/store"
	"github.com/S-kkipie/quorum/internal/proto"
)

const (
	minGap       = 30 * time.Minute
	retryGap     = 5 * time.Minute
	inactiveFor  = 7 * 24 * time.Hour
	maxSummary   = 200
	maxTitles    = 40
	maxTurnEnds  = 5
	maxAnswer    = 300
	maxRecap     = 300
	loopInterval = time.Minute
)

// Summarizer generates the summaries of touched projects.
type Summarizer struct {
	st    *store.Store
	model Model
	pub   func(proto.Envelope)
	now   func() time.Time

	mu    sync.Mutex
	dirty map[string]bool
	retry map[string]time.Time // do not retry before this time after an error
	hash  map[string]string    // last input each project was generated from
	gen   sync.Mutex           // one generation at a time

	// "where you left off" (leftoff.go): last trigger, retry deadline and last input per project.
	ldirty map[string]time.Time
	lretry map[string]time.Time
	lhash  map[string]string
	// OnLeftOff is called after a project's "where you left off" text changed (set before Start).
	OnLeftOff func(projectID string)
}

func New(st *store.Store, m Model, pub func(proto.Envelope)) *Summarizer {
	return &Summarizer{st: st, model: m, pub: pub, now: time.Now, dirty: map[string]bool{}, retry: map[string]time.Time{}, hash: map[string]string{},
		ldirty: map[string]time.Time{}, lretry: map[string]time.Time{}, lhash: map[string]string{}}
}

// Touch marks the project as changed; the loop will summarize it when due.
func (s *Summarizer) Touch(projectID string) {
	if projectID == "" {
		return
	}
	s.mu.Lock()
	s.dirty[projectID] = true
	s.mu.Unlock()
}

// Forget drops the project's state (pending, retry, last input): it was deleted.
func (s *Summarizer) Forget(projectID string) {
	s.mu.Lock()
	delete(s.dirty, projectID)
	delete(s.retry, projectID)
	delete(s.hash, projectID)
	delete(s.ldirty, projectID)
	delete(s.lretry, projectID)
	delete(s.lhash, projectID)
	s.mu.Unlock()
}

// Pending says whether the summarizer keeps any state for the project.
func (s *Summarizer) Pending(projectID string) bool {
	s.mu.Lock()
	defer s.mu.Unlock()
	_, r := s.retry[projectID]
	_, h := s.hash[projectID]
	_, ld := s.ldirty[projectID]
	_, lr := s.lretry[projectID]
	_, lh := s.lhash[projectID]
	return s.dirty[projectID] || r || h || ld || lr || lh
}

// Start launches the loop (every minute) and returns right away; stops when ctx is cancelled.
// On startup it marks projects without a summary (or without a "where you left off" text) as pending.
func (s *Summarizer) Start(ctx context.Context) {
	if ps, err := s.st.ListProjects(); err == nil {
		for _, p := range ps {
			if p.SummaryAt == 0 {
				s.Touch(p.ID)
			}
		}
		s.seedLeftOff(ps)
	}
	go func() {
		t := time.NewTicker(loopInterval)
		defer t.Stop()
		for {
			select {
			case <-ctx.Done():
				return
			case <-t.C:
				s.RunOnce(ctx)
			}
		}
	}()
}

// RunOnce processes the pending projects that are due: summaries, then "where you left off" texts.
func (s *Summarizer) RunOnce(ctx context.Context) {
	s.runSummaries(ctx)
	s.runLeftOff(ctx)
}

func (s *Summarizer) runSummaries(ctx context.Context) {
	s.mu.Lock()
	ids := make([]string, 0, len(s.dirty))
	for id := range s.dirty {
		ids = append(ids, id)
	}
	s.mu.Unlock()
	sort.Strings(ids)
	for _, id := range ids {
		if ctx.Err() != nil {
			return
		}
		s.process(ctx, id)
	}
}

func (s *Summarizer) process(ctx context.Context, id string) {
	s.gen.Lock()
	defer s.gen.Unlock()
	p, err := s.st.GetProject(id)
	if errors.Is(err, store.ErrNotFound) {
		s.Forget(id) // project deleted
		return
	}
	if err != nil {
		log.Printf("summary: project %s: %v", id, err)
		return
	}
	now := s.now()
	if p.SummaryAt != 0 && now.Sub(time.UnixMilli(p.SummaryAt)) < minGap {
		return
	}
	s.mu.Lock()
	if t, ok := s.retry[id]; ok && now.Before(t) {
		s.mu.Unlock()
		return
	}
	delete(s.dirty, id) // whatever changes during generation marks it again
	s.mu.Unlock()

	text, h, same, err := s.generate(ctx, p, now)
	if err != nil {
		log.Printf("summary: project %s: %v", id, err)
		s.mu.Lock()
		s.dirty[id] = true
		s.retry[id] = now.Add(retryGap)
		s.mu.Unlock()
		return
	}
	s.mu.Lock()
	delete(s.retry, id)
	s.mu.Unlock()
	if text == "" {
		return
	}
	if text == p.Summary && p.SummaryAt != 0 && strings.HasPrefix(text, "No activity since") {
		return // fixed text unchanged: neither stored nor published
	}
	if err := s.st.SetProjectSummary(id, text, now.UnixMilli()); err != nil {
		log.Printf("summary: save %s: %v", id, err)
		return
	}
	if h != "" {
		s.mu.Lock()
		s.hash[id] = h
		s.mu.Unlock()
	}
	if same {
		return // only the deadline was renewed: nothing visible changed
	}
	if np, err := s.st.GetProject(id); err == nil {
		pl, _ := json.Marshal(np)
		s.pub(proto.Envelope{Type: "project_upsert", Payload: pl})
	}
}

// generate returns the new text ("" = nothing to store).
func (s *Summarizer) generate(ctx context.Context, p proto.Project, now time.Time) (string, string, bool, error) {
	act, err := s.st.ProjectActivity(p.ID)
	if err != nil {
		return "", "", false, err
	}
	live := s.liveSessions(p.ID)
	// With an open session the project is not inactive, even if the tickets are old.
	if len(live) == 0 && act >= store.MinActivityMs && now.Sub(time.UnixMilli(act)) > inactiveFor {
		return "No activity since " + time.UnixMilli(act).Format("2006-01-02"), "", false, nil
	}
	tickets, err := s.st.ListTickets(p.ID)
	if err != nil {
		return "", "", false, err
	}
	if act == 0 && len(tickets) == 0 && len(live) == 0 {
		return "", "", false, nil
	}
	tes, err := s.st.ProjectTurnEnds(p.ID, maxTurnEnds)
	if err != nil {
		return "", "", false, err
	}
	sum := sha256.Sum256([]byte(buildPrompt(p, tickets, live, tes, false)))
	h := hex.EncodeToString(sum[:])
	s.mu.Lock()
	same := s.hash[p.ID] == h
	s.mu.Unlock()
	if same && p.Summary != "" {
		return p.Summary, h, true, nil // nothing changed: the deadline is renewed without calling the model
	}
	out, err := s.model.Complete(ctx, buildPrompt(p, tickets, live, tes, true))
	if err != nil {
		return "", "", false, err
	}
	out = Clean(out)
	if out == "" {
		return "", "", false, fmt.Errorf("the model returned an empty summary")
	}
	return out, h, false, nil
}

func (s *Summarizer) liveSessions(projectID string) []proto.SessionInfo {
	ss, err := s.st.ListSessions(false)
	if err != nil {
		return nil
	}
	var out []proto.SessionInfo
	for _, si := range ss {
		if si.ProjectID == projectID && si.Role != proto.RoleService {
			out = append(out, si)
		}
	}
	return out
}

func cut(s string, n int) string {
	if r := []rune(s); len(r) > n {
		return string(r[:n])
	}
	return s
}

// Clean leaves the text on one line, without wrapping quotes and at most 200 characters.
func Clean(s string) string {
	s = strings.Join(strings.Fields(s), " ")
	s = strings.Trim(s, "\"'“”«» ")
	return strings.TrimSpace(cut(s, maxSummary))
}

func buildPrompt(p proto.Project, ts []proto.Ticket, live []proto.SessionInfo, tes []proto.Event, withState bool) string {
	var b strings.Builder
	fmt.Fprintf(&b, "Project: %s\n", p.Name)
	left := maxTitles
	by := map[string][]string{}
	for _, t := range ts {
		by[t.Status] = append(by[t.Status], t.Title)
	}
	b.WriteString("\nTickets by status:\n")
	if len(ts) == 0 {
		b.WriteString("(no tickets)\n")
	}
	for _, st := range store.TicketStatuses {
		titles := by[st]
		if len(titles) == 0 {
			continue
		}
		fmt.Fprintf(&b, "- %s (%d):\n", st, len(titles))
		for _, t := range titles {
			if left == 0 {
				b.WriteString("  ...\n")
				break
			}
			left--
			fmt.Fprintf(&b, "  * %s\n", cut(oneLine(t), 120))
		}
	}
	b.WriteString("\nLive sessions:\n")
	if len(live) == 0 {
		b.WriteString("(none)\n")
	}
	for _, si := range live {
		if withState {
			fmt.Fprintf(&b, "- [%s] %s\n", si.State, cut(oneLine(si.Recap), maxRecap))
		} else {
			fmt.Fprintf(&b, "- %s\n", cut(oneLine(si.Recap), maxRecap))
		}
	}
	b.WriteString("\nLatest session answers:\n")
	n := 0
	for _, e := range tes {
		var te proto.TurnEnd
		if json.Unmarshal(e.Data, &te) != nil || strings.TrimSpace(te.Answer) == "" {
			continue
		}
		n++
		fmt.Fprintf(&b, "- %s\n", cut(oneLine(te.Answer), maxAnswer))
	}
	if n == 0 {
		b.WriteString("(none)\n")
	}
	b.WriteString("\nIn 1 or 2 sentences (max. 200 characters): where the project stands and what is holding it back. Reply with the summary only, no quotes or preamble.")
	return strings.ReplaceAll(b.String(), "\x00", "")
}

func oneLine(s string) string { return strings.Join(strings.Fields(s), " ") }
